@pytest.mark.parametrize("resample", [False, True])
def test_dataset_groupby_map_returns_dataarray(resample) -> None:
    # Regression test for GH6386: mapping may change the type of the object.
    dataset = xr.Dataset(
        {"foo": (("time", "x"), [[1, 2], [3, 4], [5, 6], [7, 8]])},
        coords={
            "time": pd.to_datetime(
                ["2000-01-01", "2000-07-01", "2001-01-01", "2001-07-01"]
            ),
            "x": ["a", "b"],
        },
    )
    if resample:
        grouped = dataset.resample(time="YS")
        dim = "time"
        labels = pd.date_range("2000-01-01", periods=2, freq="YS")
    else:
        grouped = dataset.groupby("time.year")
        dim = "year"
        labels = [2000, 2001]

    expected = xr.DataArray(
        [[2.0, 3.0], [6.0, 7.0]],
        dims=(dim, "x"),
        coords={dim: labels, "x": ["a", "b"]},
        name="foo",
    )
    actual = grouped.map(lambda group: group.foo.mean("time"))
    assert_identical(actual, expected)
    pd.testing.assert_index_equal(actual.indexes[dim], expected.indexes[dim])
    assert_identical(actual.sel({dim: labels[0]}), expected.isel({dim: 0}))


